	first := makeRecord(t, "renew-key", "fp", `{"v":"old"}`, firstAt, firstAt.Add(time.Hour))
	if _, _, err := st1.PutRecord(ctx, first, firstAt); err != nil {
		t.Fatalf("put first: %v", err)
	}

