	var wg sync.WaitGroup
	for i := 0; i < racers; i++ {
		wg.Add(1)
		go func(st *Store) {
			defer wg.Done()
			<-start
			record := makeRecord(t, "renew-key", "fp", `{"v":"new"}`, secondAt, secondAt.Add(time.Hour))
			_, outcome, err := st.PutRecord(ctx, record, secondAt)
			if err != nil {
