			}(i, j, st)
		}
	}
	close(start)
	wg.Wait()
	close(resultCh)

	var winnerID, winnerSnap string
	createdCount := 0
	for result := range resultCh {
		if winnerID == "" && result.outcome == PutCreated {
			winnerID = result.id
			winnerSnap = result.snap
		}
