			if err := json.Unmarshal([]byte(result.body), &parsed); err != nil {
				t.Fatalf("decode conflict %d: %v", i, err)
			}
			if winnerID != "" && (parsed.Error.RecordID != winnerID || parsed.Error.RequestFingerprint != winnerFingerprint) {
