	"sync"
	"time"
)

func main() {
	basePorts := []string{"18081", "18082", "18083", "18084"}
	key := os.Args[1]
	mode := os.Args[2] // same | diff
	total := 64

	expires := time.Now().UTC().Add(time.Hour).Format(time.RFC3339Nano)
	type resp struct {
		status int
		body   string
	}
	resps := make([]resp, total)
	start := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < total; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			fp := "fp-shared"
			snap := map[string]any{"worker": i}
			if mode == "diff" {
				fp = fmt.Sprintf("fp-%02d", i)
			}
			payload, _ := json.Marshal(map[string]any{
				"idempotency_key":     key,
				"request_fingerprint": fp,
				"response_snapshot":   snap,
				"expires_at":          expires,
			})
			<-start
			port := basePorts[i%len(basePorts)]
			r, err := http.Post("http://127.0.0.1:"+port+"/v1/idempotency/records",
				"application/json", bytes.NewReader(payload))
			if err != nil {
				resps[i] = resp{0, err.Error()}
				return
			}
			b, _ := io.ReadAll(r.Body)
			r.Body.Close()
			resps[i] = resp{r.StatusCode, string(b)}
		}(i)
	}
	close(start)
	wg.Wait()

	ok := 0
	conflict := 0
	other := 0
	var okBody, conflictRecord, conflictFP string
	for _, r := range resps {
		switch r.status {
		case 200:
			ok++
			if okBody == "" {
				okBody = r.body
			} else if r.body != okBody {
				fmt.Println("MISMATCH 200 bodies differ")
				os.Exit(1)
			}
		case 409:
			conflict++
			var parsed struct {
				Error struct {
					RecordID           string `json:"record_id"`
					RequestFingerprint string `json:"request_fingerprint"`
				} `json:"error"`
			}
			json.Unmarshal([]byte(r.body), &parsed)
			if conflictRecord == "" {
				conflictRecord = parsed.Error.RecordID
				conflictFP = parsed.Error.RequestFingerprint
			} else if parsed.Error.RecordID != conflictRecord || parsed.Error.RequestFingerprint != conflictFP {
				fmt.Println("MISMATCH conflict identities differ:", r.body)
				os.Exit(1)
			}
		default:
			other++
			fmt.Printf("UNEXPECTED %d %s\n", r.status, r.body)
		}
	}
	fmt.Printf("ok=%d conflict=%d other=%d\n", ok, conflict, other)
	if mode == "same" && (ok != total || conflict != 0 || other != 0) {
		os.Exit(1)
	}
	if mode == "diff" && (ok != 1 || conflict != total-1 || other != 0) {
		os.Exit(1)
	}
	if mode == "diff" {
		var parsed struct {
			Record struct {
				ID                 string `json:"id"`
				RequestFingerprint string `json:"request_fingerprint"`
			} `json:"record"`
		}
		json.Unmarshal([]byte(okBody), &parsed)
		if parsed.Record.ID != conflictRecord || parsed.Record.RequestFingerprint != conflictFP {
			fmt.Printf("CONFLICT POINTS ELSEWHERE winner=%s/%s conflicts=%s/%s\n",
				parsed.Record.ID, parsed.Record.RequestFingerprint, conflictRecord, conflictFP)
			os.Exit(1)
		}
	}
	fmt.Println("OKBODY:", okBody)
}
EOF
