{"cmd": "cd /tmp/xproc
# 先写一条已过期记录（过期校验在客户端，直接用 Go client 无法写过去时间；改用 sqlite 不行，
# 用一个带自定义过期时间的临时客户端）
cat > renew.go << 'EOF'
package main

import (
	"bytes"
	"fmt"
	"io"
	"net/http"
	"os"
	"sync"
	"time"
)

func post(body string, port string) (int, string) {
	r, err := http.Post("http://127.0.0.1:"+port+"/v1/idempotency/records",
		"application/json", bytes.NewBufferString(body))
	if err != nil {
		return 0, err.Error()
	}
	b, _ := io.ReadAll(r.Body)
	r.Body.Close()
	return r.StatusCode, string(b)
}

func main() {
	key := "k-renew"
	ports := []string{"18081", "18082", "18083", "18084"}
	old := `{"idempotency_key":"k-renew","request_fingerprint":"fp","response_snapshot":{"v":"old"},"expires_at":"` +
		time.Now().UTC().Add(-2*time.Hour).Format(time.RFC3339Nano) + `"}`
	// 旧记录无法通过 400 校验，这里改用快过期 + 等待不现实；直接让旧记录先合法写入再等待过期也太久。
	// 因此此场景由单元测试覆盖（store/api 层用注入时间），这里仅做"新 key 并发首次提交"的二次确认。
	_ = old
	expires := time.Now().UTC().Add(time.Hour).Format(time.RFC3339Nano)
	body := `{"idempotency_key":"` + key + `","request_fingerprint":"fp","response_snapshot":{"v":"new"},"expires_at":"` + expires + `"}`
	var wg sync.WaitGroup
	statuses := make([]int, 32)
	bodies := make([]string, 32)
	start := make(chan struct{})
	for i := 0; i < 32; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			statuses[i], bodies[i] = post(body, ports[i%4])
		}(i)
	}
	close(start)
	wg.Wait()
	ok, other := 0, 0
	first := ""
	for i, s := range statuses {
		if s == 200 {
			ok++
			if first == "" {
				first = bodies[i]
			} else if bodies[i] != first {
				fmt.Println("BODY MISMATCH")
				os.Exit(1)
			}
		} else {
			other++
			fmt.Println("unexpected", s, bodies[i])
		}
	}
	fmt.Printf("ok=%d other=%d\n", ok, other)
	if ok != 32 || other != 0 {
		os.Exit(1)
	}
}
EOF
go run renew.go"}

